def equilibre(texte):
    paires = {")": "(", "]": "[", "}": "{"}
    pile = []
    for c in texte:
        if c in "([{":
            pile.append(c)
        elif c in paires:
            if not pile or pile.pop() != paires[c]:
                return False
    return not pile

def postfixe(expression):
    pile = []
    for element in expression.split():
        if element in "+-*":
            b = pile.pop()
            a = pile.pop()
            if element == "+":
                pile.append(a + b)
            elif element == "-":
                pile.append(a - b)
            else:
                pile.append(a * b)
        else:
            pile.append(int(element))
    return pile.pop()

