def simplifier(chemin):
    pile = []
    for morceau in chemin.split("/"):
        if morceau in ("", "."):
            continue
        if morceau == "..":
            if pile:
                pile.pop()
        else:
            pile.append(morceau)
    return "/" + "/".join(pile)
